CREATE OR REPLACE PROCEDURE public.sp_upsert_organization_billing_settings(IN p_id uuid, IN p_tenant_id uuid, IN p_organization_id uuid, IN p_mode character varying, IN p_frequency character varying, IN p_effective_date timestamp with time zone, IN p_next_billing_date timestamp with time zone, IN p_auto_charge_enabled boolean, IN p_notes text, IN p_updated_by character varying, IN p_updated_at timestamp with time zone)  LANGUAGE plpgsql AS $procedure$ BEGIN     INSERT INTO organization_billing_settings (         id, tenant_id, organization_id, mode, frequency, effective_date,         next_billing_date, auto_charge_enabled, notes, updated_by, updated_at     ) VALUES (         p_id, p_tenant_id, p_organization_id, p_mode, p_frequency, p_effective_date,         p_next_billing_date, p_auto_charge_enabled, p_notes, p_updated_by, p_updated_at     )     ON CONFLICT (organization_id) DO UPDATE SET         mode = EXCLUDED.mode,         frequency = EXCLUDED.frequency,         effective_date = EXCLUDED.effective_date,         next_billing_date = EXCLUDED.next_billing_date,         auto_charge_enabled = EXCLUDED.auto_charge_enabled,         notes = EXCLUDED.notes,         updated_by = EXCLUDED.updated_by,         updated_at = EXCLUDED.updated_at; END; $procedure$ ;
